/* ═══════════════════════════════════════════════════════════
   STATEMENTS PAGE — Customer & Supplier account statements
   ═══════════════════════════════════════════════════════════ */
var Statements = function (props) {
  var state = props.state;
  var cur = getCurrencySymbol();

  var [mode, setMode] = useState("customer"); /* "customer" | "supplier" */
  var [selId, setSelId] = useState("");
  var [dateFrom, setDateFrom] = useState("");
  var [dateTo, setDateTo] = useState("");

  var customers = (state.customers || []).slice().sort(function (a, b) { return (a.name || "").localeCompare(b.name || ""); });
  var suppliers = (state.suppliers || []).slice().sort(function (a, b) { return (a.name || "").localeCompare(b.name || ""); });
  var people = mode === "customer" ? customers : suppliers;
  var selected = people.find(function (p) { return p.id === selId; }) || null;

  /* ── Build transaction rows ── */
  var rows = [];

  if (selected) {
    if (mode === "customer") {
      /* Sales invoices — use original total (before returns) for the debit so the
         return credit row shows the reduction cleanly without double-counting.
         We reconstruct original total = current total + sum of returns on that invoice */
      (state.sales || []).forEach(function (s) {
        if (s.customerId !== selected.id && s.customerName !== selected.name) return;
        /* Find all returns for this invoice to reconstruct original total */
        var saleReturns = (state.salesReturns || []).filter(function (r) { return r.invoiceId === s.id || r.invoiceNo === s.invoiceNo; });
        var returnedTotal = saleReturns.reduce(function (a, r) { return a + (r.amount || 0); }, 0);
        var originalTotal = s.total + returnedTotal; /* restore original invoice value */
        rows.push({ date: s.date, type: "Invoice", ref: s.invoiceNo || s.id.slice(0, 8), detail: (s.items || []).map(function (i) { return i.name + (i.qty > 1 ? " x" + i.qty : ""); }).join(", ") || "—", debit: originalTotal, credit: 0, paid: s.paid || 0, payStatus: s.payStatus });
        /* Payment history entries */
        (s.paymentHistory || []).forEach(function (ph) {
          if (ph.amount > 0) {
            rows.push({ date: ph.date || s.date, type: "Payment", ref: s.invoiceNo || s.id.slice(0, 8), detail: "Payment received" + (ph.method ? " — " + ph.method : ""), debit: 0, credit: ph.amount, paid: 0, payStatus: "" });
          }
        });
      });
      /* Sales returns — show as credit (reduces what customer owes) */
      (state.salesReturns || []).forEach(function (r) {
        if (r.customerId !== selected.id && r.customerName !== selected.name && r.customer !== selected.name) return;
        rows.push({ date: r.date, type: "Return", ref: r.invoiceNo || r.id.slice(0, 8), detail: (r.productName || "Return") + (r.reason ? " — " + r.reason : ""), debit: 0, credit: r.amount || 0, paid: 0, payStatus: "" });
      });
    } else {
      /* Purchases */
      (state.purchases || []).forEach(function (p) {
        if (p.supplier !== selected.name && p.supplierId !== selected.id) return;
        rows.push({ date: p.date, type: "Purchase", ref: p.invoiceNo || p.id.slice(0, 8), detail: (p.items || p.stock || []).map(function (i) { return i.name + (i.qty > 1 ? " x" + i.qty : ""); }).join(", ") || "—", debit: p.total, credit: 0, paid: p.paid || 0, payStatus: p.payStatus });
        (p.paymentHistory || []).forEach(function (ph) {
          if (ph.amount > 0) {
            rows.push({ date: ph.date || p.date, type: "Payment", ref: p.invoiceNo || p.id.slice(0, 8), detail: "Payment made" + (ph.method ? " — " + ph.method : ""), debit: 0, credit: ph.amount, paid: 0, payStatus: "" });
          }
        });
      });
    }
  }

  /* Sort by date ascending */
  rows.sort(function (a, b) { return (a.date || "").localeCompare(b.date || ""); });

  /* Date filter */
  var filtered = rows.filter(function (r) {
    if (dateFrom && r.date < dateFrom) return false;
    if (dateTo && r.date > dateTo) return false;
    return true;
  });

  /* Running balance */
  var running = 0;
  var withBalance = filtered.map(function (r) {
    running += (r.debit - r.credit);
    return Object.assign({}, r, { runningBalance: running });
  });

  var totalDebit = filtered.reduce(function (a, r) { return a + r.debit; }, 0);
  var totalCredit = filtered.reduce(function (a, r) { return a + r.credit; }, 0);
  var netBalance = totalDebit - totalCredit;

  /* ── Print statement ── */
  var printStatement = function () {
    if (!selected) return;
    var shopName = (state.settings && state.settings.shopName) || "Techon ERP";
    var shopAddr = (state.settings && state.settings.address) || "";
    var shopPhone = (state.settings && state.settings.phone) || "";
    var accent = (state.settings && state.settings.invoiceAccentColor) || "#0d47a1";
    var periodLabel = (dateFrom || dateTo) ? ("Period: " + (dateFrom ? fmtDate(dateFrom) : "Start") + " — " + (dateTo ? fmtDate(dateTo) : "Today")) : "All Time";
    var html = "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Statement — " + escapeHtml(selected.name) + "</title>";
    html += "<style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:'Segoe UI',Arial,sans-serif;font-size:12px;color:#111;background:#fff;padding:32px 36px;}";
    html += ".hdr{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px;padding-bottom:16px;border-bottom:2px solid " + accent + ";}";
    html += ".shop-name{font-size:20px;font-weight:900;color:" + accent + ";text-transform:uppercase;letter-spacing:-0.02em;}";
    html += ".shop-sub{font-size:11px;color:#555;margin-top:3px;}";
    html += ".stmt-title{font-size:18px;font-weight:800;color:#111;text-align:right;}";
    html += ".stmt-sub{font-size:11px;color:#666;text-align:right;margin-top:3px;}";
    html += ".party-box{background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px 16px;margin-bottom:20px;display:flex;justify-content:space-between;align-items:flex-start;}";
    html += ".party-name{font-size:15px;font-weight:800;color:#0d1b3e;}";
    html += ".party-sub{font-size:11px;color:#555;margin-top:3px;}";
    html += ".bal-box{text-align:right;}";
    html += ".bal-label{font-size:10px;font-weight:700;color:#888;text-transform:uppercase;letter-spacing:.06em;}";
    html += ".bal-val{font-size:20px;font-weight:900;color:" + (netBalance > 0 ? "#dc2626" : "#16a34a") + ";margin-top:2px;}";
    html += "table{width:100%;border-collapse:collapse;margin-bottom:20px;}";
    html += "thead tr{background:" + accent + ";color:#fff;}";
    html += "th{padding:9px 11px;font-size:11px;font-weight:700;text-align:left;}th.r{text-align:right;}";
    html += "td{padding:8px 11px;font-size:11px;border-bottom:1px solid #f0f0f0;}td.r{text-align:right;}td.bold{font-weight:700;}";
    html += "tr:nth-child(even){background:#fafbff;}";
    html += ".type-invoice{color:" + accent + ";font-weight:700;}";
    html += ".type-payment{color:#16a34a;font-weight:700;}";
    html += ".type-return{color:#d97706;font-weight:700;}";
    html += ".totals-row td{font-weight:800;border-top:2px solid " + accent + ";background:#f0f4ff;font-size:12px;}";
    html += ".footer{text-align:center;font-size:10px;color:#aaa;margin-top:20px;padding-top:12px;border-top:1px solid #e5e7eb;}";
    html += "@media print{body{padding:16px;}}</style></head><body>";
    html += "<div class='hdr'><div><div class='shop-name'>" + escapeHtml(shopName) + "</div>";
    if (shopAddr) html += "<div class='shop-sub'>" + escapeHtml(shopAddr) + "</div>";
    if (shopPhone) html += "<div class='shop-sub'>Tel: " + escapeHtml(shopPhone) + "</div>";
    html += "</div><div><div class='stmt-title'>" + (mode === "customer" ? "Customer" : "Supplier") + " Statement</div>";
    html += "<div class='stmt-sub'>" + escapeHtml(periodLabel) + "</div>";
    html += "<div class='stmt-sub'>Printed: " + new Date().toLocaleString() + "</div></div></div>";
    html += "<div class='party-box'><div><div class='party-name'>" + escapeHtml(selected.name) + "</div>";
    if (selected.phone) html += "<div class='party-sub'>📞 " + escapeHtml(selected.phone) + "</div>";
    if (selected.address) html += "<div class='party-sub'>📍 " + escapeHtml(selected.address) + "</div>";
    html += "</div><div class='bal-box'><div class='bal-label'>Outstanding Balance</div><div class='bal-val'>" + cur + " " + fmtNum(Math.abs(netBalance)) + (netBalance <= 0 ? " CR" : "") + "</div></div></div>";
    html += "<table><thead><tr><th>Date</th><th>Type</th><th>Reference</th><th>Details</th><th class='r'>Debit (" + cur + ")</th><th class='r'>Credit (" + cur + ")</th><th class='r'>Balance (" + cur + ")</th></tr></thead><tbody>";
    withBalance.forEach(function (r) {
      var typeClass = r.type === "Invoice" || r.type === "Purchase" ? "type-invoice" : r.type === "Payment" ? "type-payment" : "type-return";
      html += "<tr><td>" + escapeHtml(fmtDate(r.date)) + "</td>";
      html += "<td><span class='" + typeClass + "'>" + escapeHtml(r.type) + "</span></td>";
      html += "<td class='bold'>" + escapeHtml(r.ref) + "</td>";
      html += "<td style='max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;'>" + escapeHtml(r.detail) + "</td>";
      html += "<td class='r'>" + (r.debit > 0 ? fmtNum(r.debit) : "—") + "</td>";
      html += "<td class='r' style='color:#16a34a;'>" + (r.credit > 0 ? fmtNum(r.credit) : "—") + "</td>";
      html += "<td class='r bold' style='color:" + (r.runningBalance > 0 ? "#dc2626" : "#16a34a") + ";'>" + fmtNum(Math.abs(r.runningBalance)) + (r.runningBalance <= 0 ? " CR" : "") + "</td></tr>";
    });
    html += "<tr class='totals-row'><td colspan='4'>TOTALS</td><td class='r'>" + fmtNum(totalDebit) + "</td><td class='r'>" + fmtNum(totalCredit) + "</td><td class='r' style='color:" + (netBalance > 0 ? "#dc2626" : "#16a34a") + ";'>" + fmtNum(Math.abs(netBalance)) + (netBalance <= 0 ? " CR" : "") + "</td></tr>";
    html += "</tbody></table>";
    html += "<div class='footer'>Powered by TechonERP • www.erp.techon.lk</div></body></html>";
    var w = window.open("", "_blank", "width=900,height=700");
    if (!w) return;
    w.document.write(html);
    w.document.close();
    w.focus();
    setTimeout(function () { w.print(); }, 400);
  };

  var TH2 = function (p) { return <th style={{ padding: "10px 12px", textAlign: p.right ? "right" : "left", fontWeight: 700, fontSize: 12, background: "linear-gradient(90deg,#0d47a1,#1565c0)", color: "#fff", whiteSpace: "nowrap" }}>{p.children}</th>; };

  return (
    <div style={{ padding: "20px 24px", maxWidth: 1100, margin: "0 auto" }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20, flexWrap: "wrap", gap: 12 }}>
        <div>
          <div style={{ fontSize: 22, fontWeight: 900, color: C.text, letterSpacing: "-0.03em" }}>📋 Account Statements</div>
          <div style={{ fontSize: 13, color: C.muted, marginTop: 3 }}>Full transaction history for customers and suppliers</div>
        </div>
        {selected && withBalance.length > 0 && (
          <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
            <Btn col="blue" onClick={printStatement}>🖨 Print Statement</Btn>
            <WABtn title="Share Statement via WhatsApp" onClick={function () { shareAnyReport(printStatement, "Statement-" + (selected || "account")); }} />
          </div>
        )}
      </div>

      {/* Controls */}
      <div style={{ background: "#fff", border: "1.5px solid " + C.border, borderRadius: 12, padding: "16px 20px", marginBottom: 20, display: "flex", flexWrap: "wrap", gap: 14, alignItems: "flex-end" }}>
        {/* Mode toggle */}
        <div>
          <div style={{ fontSize: 11, fontWeight: 700, color: C.textMd, textTransform: "uppercase", letterSpacing: "0.07em", marginBottom: 6 }}>Statement Type</div>
          <div style={{ display: "flex", border: "1.5px solid " + C.border, borderRadius: 8, overflow: "hidden" }}>
            {[["customer", "👤 Customer"], ["supplier", "🏭 Supplier"]].map(function (opt) {
              var active = mode === opt[0];
              return <button key={opt[0]} onClick={function () { setMode(opt[0]); setSelId(""); }}
                style={{ padding: "8px 18px", border: "none", cursor: "pointer", fontWeight: active ? 700 : 500, fontSize: 13,
                  background: active ? C.accent : "#fff", color: active ? "#fff" : C.textMd, fontFamily: "inherit", transition: "all .15s" }}>{opt[1]}</button>;
            })}
          </div>
        </div>
        {/* Party selector */}
        <div style={{ flex: 1, minWidth: 200 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: C.textMd, textTransform: "uppercase", letterSpacing: "0.07em", marginBottom: 6 }}>{mode === "customer" ? "Select Customer" : "Select Supplier"}</div>
          <select value={selId} onChange={function (e) { setSelId(e.target.value); }}
            style={{ width: "100%", border: "1.5px solid " + C.border, borderRadius: 8, padding: "9px 12px", fontSize: 13, background: "#fff", color: C.text, outline: "none", cursor: "pointer", fontFamily: "inherit" }}>
            <option value="">— Select {mode === "customer" ? "a customer" : "a supplier"} —</option>
            {people.map(function (p) { return <option key={p.id} value={p.id}>{p.name}{p.phone ? "  ·  " + p.phone : ""}</option>; })}
          </select>
        </div>
        {/* Date range */}
        <div>
          <div style={{ fontSize: 11, fontWeight: 700, color: C.textMd, textTransform: "uppercase", letterSpacing: "0.07em", marginBottom: 6 }}>From Date</div>
          <input type="date" value={dateFrom} onChange={function (e) { setDateFrom(e.target.value); }}
            style={{ border: "1.5px solid " + C.border, borderRadius: 8, padding: "9px 12px", fontSize: 13, outline: "none", fontFamily: "inherit", background: "#fff", color: C.text }} />
        </div>
        <div>
          <div style={{ fontSize: 11, fontWeight: 700, color: C.textMd, textTransform: "uppercase", letterSpacing: "0.07em", marginBottom: 6 }}>To Date</div>
          <input type="date" value={dateTo} onChange={function (e) { setDateTo(e.target.value); }}
            style={{ border: "1.5px solid " + C.border, borderRadius: 8, padding: "9px 12px", fontSize: 13, outline: "none", fontFamily: "inherit", background: "#fff", color: C.text }} />
        </div>
        {(dateFrom || dateTo) && (
          <button onClick={function () { setDateFrom(""); setDateTo(""); }} style={{ alignSelf: "flex-end", padding: "9px 14px", background: "#f1f5f9", border: "1.5px solid " + C.border, borderRadius: 8, fontSize: 12, fontWeight: 700, color: C.textMd, cursor: "pointer", fontFamily: "inherit" }}>✕ Clear</button>
        )}
      </div>

      {/* Party summary card */}
      {selected && (
        <div style={{ background: "linear-gradient(135deg,#0d47a1,#1565c0)", borderRadius: 12, padding: "16px 22px", marginBottom: 20, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 12 }}>
          <div>
            <div style={{ fontSize: 18, fontWeight: 900, color: "#fff" }}>{selected.name}</div>
            {selected.phone && <div style={{ fontSize: 12, color: "rgba(255,255,255,0.75)", marginTop: 3 }}>📞 {selected.phone}</div>}
            {selected.address && <div style={{ fontSize: 12, color: "rgba(255,255,255,0.75)", marginTop: 2 }}>📍 {selected.address}</div>}
          </div>
          <div style={{ display: "flex", gap: 20, flexWrap: "wrap" }}>
            {[
              ["Total " + (mode === "customer" ? "Billed" : "Purchased"), totalDebit, "#93c5fd"],
              ["Total Paid", totalCredit, "#86efac"],
              ["Outstanding", Math.abs(netBalance), netBalance > 0 ? "#fca5a5" : "#86efac"]
            ].map(function (stat) {
              return <div key={stat[0]} style={{ textAlign: "right" }}>
                <div style={{ fontSize: 10, fontWeight: 700, color: "rgba(255,255,255,0.6)", textTransform: "uppercase", letterSpacing: "0.07em" }}>{stat[0]}</div>
                <div style={{ fontSize: 18, fontWeight: 900, color: stat[2], marginTop: 2 }}>{cur} {fmtNum(stat[1])}{stat[0] === "Outstanding" && netBalance <= 0 ? " CR" : ""}</div>
              </div>;
            })}
          </div>
        </div>
      )}

      {/* No selection state */}
      {!selected && (
        <div style={{ background: "#fff", border: "1.5px solid " + C.border, borderRadius: 12, padding: "60px 20px", textAlign: "center" }}>
          <div style={{ fontSize: 40, marginBottom: 14 }}>📋</div>
          <div style={{ fontSize: 16, fontWeight: 700, color: C.text, marginBottom: 6 }}>Select a {mode === "customer" ? "Customer" : "Supplier"}</div>
          <div style={{ fontSize: 13, color: C.muted }}>Choose from the dropdown above to view their full account statement</div>
        </div>
      )}

      {/* Transactions table */}
      {selected && withBalance.length === 0 && (
        <div style={{ background: "#fff", border: "1.5px solid " + C.border, borderRadius: 12, padding: "50px 20px", textAlign: "center" }}>
          <div style={{ fontSize: 32, marginBottom: 12 }}>🔍</div>
          <div style={{ fontSize: 15, fontWeight: 700, color: C.text, marginBottom: 6 }}>No transactions found</div>
          <div style={{ fontSize: 13, color: C.muted }}>No records found for {selected.name}{(dateFrom || dateTo) ? " in this date range" : ""}</div>
        </div>
      )}

      {selected && withBalance.length > 0 && (
        <div style={{ background: "#fff", border: "1.5px solid " + C.border, borderRadius: 12, overflow: "hidden" }}>
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
              <thead>
                <tr>
                  <TH2>Date</TH2>
                  <TH2>Type</TH2>
                  <TH2>Reference</TH2>
                  <TH2>Details</TH2>
                  <TH2 right>Debit ({cur})</TH2>
                  <TH2 right>Credit ({cur})</TH2>
                  <TH2 right>Balance ({cur})</TH2>
                </tr>
              </thead>
              <tbody>
                {withBalance.map(function (r, i) {
                  var typeColor = r.type === "Invoice" || r.type === "Purchase" ? C.accent : r.type === "Payment" ? C.green : "#d97706";
                  var typeBg = r.type === "Invoice" || r.type === "Purchase" ? C.accentSoft : r.type === "Payment" ? "#dcfce7" : "#fef9c3";
                  return (
                    <tr key={i} style={{ borderBottom: "1px solid " + C.border, background: i % 2 === 0 ? "#fff" : "#fafbff" }}>
                      <td style={{ padding: "10px 12px", color: C.textMd, fontSize: 12, whiteSpace: "nowrap" }}>{fmtDate(r.date)}</td>
                      <td style={{ padding: "10px 12px" }}>
                        <span style={{ display: "inline-block", padding: "3px 9px", borderRadius: 20, fontSize: 11, fontWeight: 700, background: typeBg, color: typeColor }}>{r.type}</span>
                      </td>
                      <td style={{ padding: "10px 12px", fontWeight: 700, color: C.text, whiteSpace: "nowrap" }}>{r.ref}</td>
                      <td style={{ padding: "10px 12px", color: C.textMd, maxWidth: 260, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }} title={r.detail}>{r.detail}</td>
                      <td style={{ padding: "10px 12px", textAlign: "right", fontWeight: 600, color: r.debit > 0 ? C.red : C.muted }}>{r.debit > 0 ? fmtNum(r.debit) : "—"}</td>
                      <td style={{ padding: "10px 12px", textAlign: "right", fontWeight: 600, color: r.credit > 0 ? C.green : C.muted }}>{r.credit > 0 ? fmtNum(r.credit) : "—"}</td>
                      <td style={{ padding: "10px 12px", textAlign: "right", fontWeight: 800, color: r.runningBalance > 0 ? C.red : C.green }}>
                        {fmtNum(Math.abs(r.runningBalance))}{r.runningBalance <= 0 ? <span style={{ fontSize: 10, marginLeft: 3 }}>CR</span> : ""}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
              <tfoot>
                <tr style={{ background: "linear-gradient(90deg,#f0f4ff,#e8eeff)", borderTop: "2px solid " + C.accent }}>
                  <td colSpan={4} style={{ padding: "11px 12px", fontWeight: 800, fontSize: 13, color: C.text }}>TOTALS</td>
                  <td style={{ padding: "11px 12px", textAlign: "right", fontWeight: 800, color: C.red }}>{fmtNum(totalDebit)}</td>
                  <td style={{ padding: "11px 12px", textAlign: "right", fontWeight: 800, color: C.green }}>{fmtNum(totalCredit)}</td>
                  <td style={{ padding: "11px 12px", textAlign: "right", fontWeight: 900, fontSize: 14, color: netBalance > 0 ? C.red : C.green }}>
                    {fmtNum(Math.abs(netBalance))}{netBalance <= 0 ? <span style={{ fontSize: 10, marginLeft: 3 }}>CR</span> : ""}
                  </td>
                </tr>
              </tfoot>
            </table>
          </div>
          <div style={{ padding: "12px 16px", background: "#f8fafc", borderTop: "1px solid " + C.border, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
            <div style={{ fontSize: 12, color: C.muted }}>{withBalance.length} transaction{withBalance.length !== 1 ? "s" : ""}{(dateFrom || dateTo) ? " in selected period" : " — all time"}</div>
            <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
              <Btn col="blue" onClick={printStatement}>🖨 Print / Save PDF</Btn>
              <WABtn title="Share Statement via WhatsApp" onClick={function () { shareAnyReport(printStatement, "Statement-" + (selected || "account")); }} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

/* ─── STARTUP ONBOARDING (steps 2–5 after mode wizard: admin → industry → shop → lang) ─ */
var StartupOnboardingWizard = function (props) {
  var state = props.state;
  var setState = props.setState;
  var systemConfig = props.systemConfig;
  var licenseInfo = props.licenseInfo;
  var onActivate = props.onActivate;
  var setBusinessType = props.setBusinessType;
  var onFinished = props.onFinished;

  var [phase, setPhase] = useState(function () {
    var ad = (S.get("tc3_admin_name", "") || "").trim();
    if (ad.length < 2) return "admin";
    if (!S.get("tc3_businessType")) return "industry";
    return "shop";
  });
  var [adminName, setAdminName] = useState(function () { return S.get("tc3_admin_name", "") || ""; });

  var steps = [
    { id: "admin", n: 2, label: "Admin" },
    { id: "industry", n: 3, label: "Industry" },
    { id: "shop", n: 4, label: "Shop" },
    { id: "lang", n: 5, label: "Language" },
  ];

  var goAdmin = function () {
    var t = adminName.trim();
    if (t.length < 2) { showAlert("Please enter your name (at least 2 characters)."); return; }
    S.set("tc3_admin_name", t);
    setPhase("industry");
  };

  useEffect(function () {
    try {
      sessionStorage.setItem("tc3_startup_wizard_session", "1");
    } catch (e) { /* ignore */ }
  }, []);

  var stepOf5 = phase === "admin" ? 2 : phase === "industry" ? 3 : phase === "shop" ? 4 : 5;
  var dpProgress = getOnboardingDataProgress(state.settings);
  var wizTitles = {
    industry: { title: "What type of business are you setting up?", sub: "Choose one — you can't change this later." },
    shop: { title: "Tell us about your shop", sub: "We use this on invoices and receipts. You can edit details anytime in Settings." },
    lang: { title: "Language, currency & tax", sub: "Match your region and how invoices print. You can adjust these later in Settings." },
  };
  var goWizardBack = function () {
    if (phase === "industry") setPhase("admin");
    else if (phase === "shop") setPhase("industry");
    else if (phase === "lang") setPhase("shop");
  };
  var canWizardBack = phase === "industry" || phase === "shop" || phase === "lang";

  /* Settings.jsx expects the same module-level helpers as <ActivePage /> — wizard embedded paths must pass them explicitly */
  var wizSettingsProps = {
    S: S,
    C: C,
    today: today,
    uid: uid,
    showAlert: showAlert,
    showConfirm: showConfirm,
    pwMatchesAsync: pwMatchesAsync,
    hashPw: hashPw,
    getCurrencySymbol: getCurrencySymbol,
    updateCurrencySymbol: updateCurrencySymbol,
    fmtNum: fmtNum,
    fmtDate: fmtDate,
    fmtDateFull: fmtDateFull,
    validateCoreStartupIdentity: validateCoreStartupIdentity,
    getCoreStartupIdentityAlertMessage: getCoreStartupIdentityAlertMessage,
    getBusinessProfile: getBusinessProfile,
    _idbCache: _idbCache,
    _idbWrite: _idbWrite,
    AboutTab: AboutTab,
    InvoiceThermal: InvoiceThermal,
    InvoiceA4: InvoiceA4,
    Input: Input,
    Btn: Btn,
    Card: Card,
    CardTitle: CardTitle,
    Sel: Sel,
    Modal: Modal,
    StatCard: StatCard,
    createFinancialSnapshot: function (opts) {
      var lines = S.get("tc3_journal_lines", []);
      var chart = S.get("tc3_gl_accounts", DEFAULT_GL_CHART);
      var invDer = deriveInventoryEconomics(loadState(), S);
      invDer.reconciliation = reconcileInventoryToLedger(lines, invDer, chart);
      var snap = buildFinancialSnapshot(S, lines, chart, invDer, opts || {});
      appendSnapshot(S, snap, { addAudit: addAudit });
      setState(loadState());
      showAlert("Financial snapshot saved and sealed (" + (snap.id || "ok") + ").");
    },
    repairInventoryLayersFromReplay: function () {
      showConfirm(
        "Inventory / journal repair will replay all transactions to rebuild the ledger and inventory layers.\n\nA JSON backup file will be downloaded first. Continue?",
        function () {
          if (!downloadPreRepairJsonBackup()) {
            showAlert("Backup download failed — repair cancelled.");
            addAudit("Repair cancelled", "inventory_layers", { reason: "backup_failed" });
            return;
          }
          addAudit("Repair started", "inventory_layers", { source: "repair_layers" });
          var r = persistTechonGLJournal("repair_layers");
          var ok = r && r.validate && r.validate.ok && r.valid;
          addAudit("Repair finished", "inventory_layers", { source: "repair_layers", ok: !!ok, warnings: r && r.warnings ? r.warnings.slice(0, 30) : [] });
          if (ok) {
            setState(loadState());
            showAlert("Inventory layers updated from full transaction replay.");
          } else {
            showAlert("Repair did not apply — resolve journal warnings or check the console.");
          }
        }
      );
    },
  };

  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 10001,
      background: "linear-gradient(160deg,#0f172a 0%,#1e1b4b 42%,#0f172a 100%)",
      fontFamily: "'Plus Jakarta Sans',system-ui,sans-serif",
      overflowY: "auto",
      padding: "28px 18px 48px",
      boxSizing: "border-box"
    }}>
      <div style={{ maxWidth: 920, margin: "0 auto" }}>
        {phase === "admin" ? (
          <React.Fragment>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18, flexWrap: "wrap" }}>
              <img src={TECHON_LOGO} alt="" style={{ width: 36, height: 36, borderRadius: 10 }} />
              <div>
                <div style={{ fontSize: 11, fontWeight: 800, color: "rgba(138,170,212,0.9)", letterSpacing: "0.12em", textTransform: "uppercase" }}>Setup Wizard</div>
                <div style={{ fontSize: 16, fontWeight: 900, color: "#fff" }}>Welcome — let&apos;s finish your profile</div>
              </div>
            </div>
            <div style={{ marginBottom: 14 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6, flexWrap: "wrap", gap: 6 }}>
                <span style={{ fontSize: 12, fontWeight: 800, color: "rgba(200,220,255,0.95)" }}>Step {stepOf5} of 5</span>
                <span style={{ fontSize: 11, fontWeight: 700, color: "rgba(138,170,212,0.9)" }}>Profile data {dpProgress.done}/{dpProgress.total} · {dpProgress.pct}%</span>
              </div>
              <div style={{ height: 6, borderRadius: 99, background: "rgba(255,255,255,0.1)", overflow: "hidden" }}>
                <div style={{ height: "100%", width: dpProgress.pct + "%", borderRadius: 99, background: "linear-gradient(90deg,#6366f1,#3b82f6)", transition: "width .28s ease" }} />
              </div>
            </div>
            <div style={{ background: "#fff", borderRadius: 16, padding: 24, border: "1px solid #e2e8f0", boxShadow: "0 12px 40px rgba(0,0,0,0.15)" }}>
              <div style={{ fontSize: 18, fontWeight: 900, color: "#0d1b3e", marginBottom: 8 }}>Administrator</div>
              <div style={{ fontSize: 13, color: "#64748b", marginBottom: 16 }}>This name appears in the sidebar. You can change it later in Settings.</div>
              <Input label="Your name" value={adminName} onChange={function (e) { setAdminName(e.target.value); }} placeholder="e.g. Rashid" />
              <div style={{ marginTop: 16 }}><Btn col="cyan" onClick={goAdmin}>Continue</Btn></div>
            </div>
          </React.Fragment>
        ) : (
          <React.Fragment>
            <div style={{
              background: "linear-gradient(135deg,#1e293b 0%,#312e81 55%,#1e1b4b 100%)",
              borderRadius: "16px 16px 0 0",
              padding: "18px 22px 16px",
              border: "1px solid rgba(255,255,255,0.08)",
              borderBottom: "none",
              boxShadow: "0 4px 24px rgba(0,0,0,0.2)",
            }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <span style={{ fontSize: 22 }} aria-hidden>🚀</span>
                  <span style={{ fontSize: 17, fontWeight: 900, color: "#f8fafc", letterSpacing: "-0.02em" }}>Setup Wizard</span>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <span style={{ fontSize: 13, fontWeight: 700, color: "rgba(226,232,240,0.95)" }}>Step {stepOf5} of 5</span>
                  <div style={{ display: "flex", gap: 4 }}>
                    <button type="button" onClick={function () { if (canWizardBack) goWizardBack(); }} disabled={!canWizardBack}
                      style={{
                        width: 34, height: 34, borderRadius: 8, border: "1px solid rgba(255,255,255,0.15)", background: canWizardBack ? "rgba(255,255,255,0.08)" : "rgba(255,255,255,0.03)",
                        color: canWizardBack ? "#e2e8f0" : "rgba(148,163,184,0.5)", cursor: canWizardBack ? "pointer" : "default", fontSize: 15, lineHeight: 1, display: "flex", alignItems: "center", justifyContent: "center",
                      }} title="Back">‹</button>
                    <button type="button" disabled style={{
                      width: 34, height: 34, borderRadius: 8, border: "1px solid rgba(255,255,255,0.08)", background: "rgba(255,255,255,0.04)",
                      color: "rgba(148,163,184,0.45)", cursor: "default", fontSize: 15, lineHeight: 1, display: "flex", alignItems: "center", justifyContent: "center",
                    }} title="Next step">›</button>
                  </div>
                </div>
              </div>
              <div style={{ marginTop: 14 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6, flexWrap: "wrap", gap: 6 }}>
                  <span style={{ fontSize: 11, fontWeight: 700, color: "rgba(148,163,184,0.95)" }}>Profile setup</span>
                  <span style={{ fontSize: 11, fontWeight: 700, color: "rgba(165,180,252,0.95)" }}>{dpProgress.done}/{dpProgress.total} · {dpProgress.pct}%</span>
                </div>
                <div style={{ height: 8, borderRadius: 99, background: "rgba(255,255,255,0.12)", overflow: "hidden" }}>
                  <div style={{ height: "100%", width: dpProgress.pct + "%", borderRadius: 99, background: "linear-gradient(90deg,#818cf8,#38bdf8)", transition: "width .35s cubic-bezier(.4,0,.2,1)" }} />
                </div>
              </div>
            </div>
            <div style={{
              background: "#fafbfc",
              borderRadius: "0 0 16px 16px",
              border: "1px solid #e2e8f0",
              borderTop: "1px solid #e8ecf4",
              boxShadow: "0 24px 48px rgba(15,23,42,0.12)",
              overflow: "hidden",
            }}>
              <div style={{ padding: "28px 28px 8px", background: "#fff" }}>
                <div style={{ fontSize: 24, fontWeight: 900, color: "#0f172a", letterSpacing: "-0.03em", lineHeight: 1.25, textAlign: "center" }}>
                  {wizTitles[phase] ? wizTitles[phase].title : ""}
                </div>
                <div style={{ fontSize: 14, color: "#64748b", marginTop: 10, fontWeight: 500, lineHeight: 1.5, textAlign: "center", maxWidth: 560, marginLeft: "auto", marginRight: "auto" }}>
                  {wizTitles[phase] ? wizTitles[phase].sub : ""}
                </div>
              </div>
              <div style={{ padding: "8px 24px 32px", background: "#fff" }}>
                {phase === "industry" && (
                  <BusinessTypeSelector embedInWizard={true} onBack={goWizardBack} onSelect={function (bt) { setBusinessType(bt); setPhase("shop"); }} />
                )}
                {phase === "shop" && (
                  <Settings
                    key="wiz-shop"
                    {...wizSettingsProps}
                    state={state}
                    setState={setState}
                    licenseInfo={licenseInfo}
                    onActivate={onActivate}
                    systemConfig={systemConfig}
                    embeddedWizard="shop_limited"
                    wizardUi={true}
                    onWizardBack={goWizardBack}
                    onWizardNext={function () { setPhase("lang"); }}
                  />
                )}
                {phase === "lang" && (
                  <Settings
                    key="wiz-lang"
                    {...wizSettingsProps}
                    state={state}
                    setState={setState}
                    licenseInfo={licenseInfo}
                    onActivate={onActivate}
                    systemConfig={systemConfig}
                    embeddedWizard="langcurrency"
                    wizardUi={true}
                    onWizardBack={goWizardBack}
                    onWizardComplete={onFinished}
                  />
                )}
              </div>
            </div>
          </React.Fragment>
        )}
      </div>
    </div>
  );
};

/* ─── BUSINESS TYPE SELECTOR (shown on first launch for new installs) ──────── */
var BusinessTypeSelector = function (props) {
  var onSelect = props.onSelect;
  var onBack = props.onBack;
  var embed = props.embedInWizard === true;
  var [search, setSearch] = useState("");
  var [hovered, setHovered] = useState(null);
  var [selected, setSelected] = useState(null);
  var [confirming, setConfirming] = useState(false);
  var [expandKey, setExpandKey] = useState(null);

  var PROFILE_KEYS = ["tech", "grocery", "fashion", "hardware", "pharmacy", "jewelry", "automotive", "agriculture", "general"];

  /* Filter cards based on search */
  var query = search.trim().toLowerCase();
  var filtered = PROFILE_KEYS.filter(function (k) {
    if (!query) return true;
    var p = BUSINESS_PROFILES[k];
    return (
      p.name.toLowerCase().includes(query) ||
      p.covers.toLowerCase().includes(query) ||
      k.toLowerCase().includes(query)
    );
  });

  var handleCardClick = function (key) {
    if (confirming) return;
    setSelected(key);
  };

  var handleConfirm = function () {
    if (!selected) return;
    setConfirming(true);
    S.set("tc3_businessType", selected);
    setTimeout(function () { onSelect(selected); }, 400);
  };

  var profile = selected ? BUSINESS_PROFILES[selected] : null;

  var whatsIncludedLine = function (p) {
    var bits = [];
    if (p.modules.repairs) bits.push("Repairs");
    if (p.modules.expiry) bits.push("Expiry");
    if (p.modules.serial) bits.push("Serial tracking");
    if (p.modules.barcode) bits.push("Barcode labels");
    return bits.length ? bits.join(", ") : "Retail essentials";
  };

  /* Light-panel UX on ERP dark blue — reference: clean white cards, navy text */
  var LP = {
    paper: "#ffffff",
    text: "#1e293b",
    muted: "#64748b",
    border: "#e2e8f0",
    inputBg: "#f8fafc",
    shadow: "0 12px 40px rgba(0,0,0,0.12), 0 4px 12px rgba(0,0,0,0.06)",
    cardShadow: "0 2px 8px rgba(15,23,42,0.06)",
    selRing: "#3b82f6",
    selBg: "#eff6ff",
  };

  if (embed) {
    return (
      <div style={{ fontFamily: "'Plus Jakarta Sans',system-ui,sans-serif" }}>
        <div style={{ position: "relative", marginBottom: 22 }}>
          <span style={{ position: "absolute", left: 16, top: "50%", transform: "translateY(-50%)", fontSize: 17, opacity: 0.4, pointerEvents: "none" }} aria-hidden>🔍</span>
          <input
            autoFocus
            type="text"
            placeholder="Search business type…"
            value={search}
            onChange={function (e) { setSearch(e.target.value); setSelected(null); }}
            style={{
              width: "100%", boxSizing: "border-box", padding: "15px 46px 15px 48px",
              background: "#f8fafc", border: "1.5px solid #e2e8f0", borderRadius: 999,
              fontSize: 15, color: "#0f172a", outline: "none", fontWeight: 500,
              boxShadow: "0 1px 2px rgba(15,23,42,0.04)",
            }}
            onFocus={function (e) { e.target.style.borderColor = "#6366f1"; e.target.style.boxShadow = "0 0 0 3px rgba(99,102,241,0.2)"; }}
            onBlur={function (e) { e.target.style.borderColor = "#e2e8f0"; e.target.style.boxShadow = "none"; }}
          />
          {search ? (
            <button type="button" onClick={function () { setSearch(""); setSelected(null); }} style={{ position: "absolute", right: 14, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", color: "#94a3b8", fontSize: 22, cursor: "pointer", lineHeight: 1, padding: 4 }} aria-label="Clear search">×</button>
          ) : null}
        </div>
        {filtered.length === 0 ? (
          <div style={{ textAlign: "center", padding: "36px 12px", color: LP.muted, fontSize: 14 }}>
            No business type matched &quot;{search}&quot;. Try another keyword or choose <strong style={{ color: LP.text }}>General Retail &amp; Services</strong>.
          </div>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: 16 }}>
            {filtered.map(function (key) {
              var p = BUSINESS_PROFILES[key];
              var isSelected = selected === key;
              var isHov = hovered === key;
              var isEx = expandKey === key;
              var covParts = (p.covers || "").split("·");
              var covShort = covParts.slice(0, 3).map(function (s) { return s.trim(); }).filter(Boolean).join(" · ");
              return (
                <div
                  key={key}
                  role="button"
                  tabIndex={0}
                  onKeyDown={function (e) { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); handleCardClick(key); } }}
                  onClick={function () { handleCardClick(key); }}
                  onMouseEnter={function () { setHovered(key); }}
                  onMouseLeave={function () { setHovered(null); }}
                  style={{
                    position: "relative",
                    background: isSelected ? "#eff6ff" : "#ffffff",
                    border: isSelected ? "2px solid #3b82f6" : "1px solid " + (isHov ? "#cbd5e1" : "#e8ecf4"),
                    borderRadius: 16,
                    padding: "18px 18px 0",
                    cursor: "pointer",
                    transition: "box-shadow .2s, transform .18s, border-color .18s",
                    boxShadow: isSelected ? "0 10px 32px rgba(59,130,246,0.18)" : isHov ? "0 6px 20px rgba(15,23,42,0.08)" : "0 2px 12px rgba(15,23,42,0.06)",
                    transform: isHov ? "scale(1.01)" : "scale(1)",
                    overflow: "hidden",
                  }}
                >
                  {isSelected ? (
                    <div style={{ position: "absolute", top: 12, right: 12, fontSize: 10, fontWeight: 900, color: "#fff", background: "linear-gradient(135deg,#3b82f6,#2563eb)", padding: "4px 10px", borderRadius: 8, letterSpacing: "0.04em" }}>SELECTED</div>
                  ) : null}
                  <div style={{ display: "flex", gap: 14, alignItems: "flex-start" }}>
                    <div style={{ fontSize: 36, lineHeight: 1, flexShrink: 0 }}>{p.emoji}</div>
                    <div style={{ flex: 1, minWidth: 0, paddingRight: isSelected ? 72 : 0 }}>
                      <div style={{ fontSize: 16, fontWeight: 900, color: "#0f172a", letterSpacing: "-0.02em", marginBottom: 6 }}>{p.name}</div>
                      <div style={{ fontSize: 12, color: "#64748b", lineHeight: 1.5, fontWeight: 500 }}>{covShort}</div>
                      <div style={{ fontSize: 12, color: "#047857", fontWeight: 700, marginTop: 12, display: "flex", alignItems: "flex-start", gap: 6, lineHeight: 1.45 }}>
                        <span aria-hidden style={{ flexShrink: 0 }}>✔</span>
                        <span>What&apos;s included: {whatsIncludedLine(p)}</span>
                      </div>
                    </div>
                  </div>
                  {isEx ? (
                    <div style={{ marginTop: 14, paddingTop: 14, borderTop: "1px solid #e8edf4", animation: "fadeIn .2s ease" }}>
                      <div style={{ fontSize: 10, fontWeight: 900, color: "#64748b", letterSpacing: "0.12em", marginBottom: 8 }}>MODULES</div>
                      <ul style={{ margin: 0, paddingLeft: 18, fontSize: 12, color: "#334155", lineHeight: 1.65 }}>
                        {p.modules.repairs ? <li>Repair &amp; service tickets</li> : null}
                        <li>Barcode &amp; product labels</li>
                        {p.modules.serial ? <li>Serial / IMEI tracking</li> : null}
                        {p.modules.expiry ? <li>Batch &amp; expiry dates</li> : null}
                      </ul>
                      <div style={{ fontSize: 10, fontWeight: 900, color: "#64748b", letterSpacing: "0.12em", margin: "14px 0 8px" }}>UNITS</div>
                      <div style={{ fontSize: 12, color: "#475569", lineHeight: 1.55 }}>{(p.units || []).join(", ")}</div>
                      <div style={{ fontSize: 10, fontWeight: 900, color: "#64748b", letterSpacing: "0.12em", margin: "14px 0 8px" }}>CATEGORIES</div>
                      <div style={{ fontSize: 12, color: "#475569", lineHeight: 1.55, maxHeight: 120, overflowY: "auto" }}>{(p.categories || []).slice(0, 14).join(" · ")}{(p.categories || []).length > 14 ? " · …" : ""}</div>
                    </div>
                  ) : null}
                  <button
                    type="button"
                    onClick={function (e) { e.stopPropagation(); setExpandKey(isEx ? null : key); }}
                    style={{
                      width: "calc(100% + 36px)", marginLeft: -18, marginRight: -18, marginTop: 14,
                      padding: "12px 16px", border: "none", borderTop: "1px solid #eef2f7",
                      background: "linear-gradient(180deg,#fafbfc 0%,#f1f5f9 100%)",
                      cursor: "pointer", fontSize: 13, fontWeight: 800, color: "#2563eb",
                      borderRadius: 0,
                      fontFamily: "inherit",
                    }}
                  >
                    {isEx ? "Hide details \u25b4" : "See what\u2019s included \u25be"}
                  </button>
                </div>
              );
            })}
          </div>
        )}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 14, marginTop: 28, paddingTop: 22, borderTop: "1px solid #e8ecf4", flexWrap: "wrap" }}>
          <button
            type="button"
            onClick={function () { if (onBack) onBack(); }}
            style={{
              padding: "12px 22px", borderRadius: 12, border: "1.5px solid #e2e8f0", background: "#fff",
              fontSize: 14, fontWeight: 800, color: "#475569", cursor: "pointer", fontFamily: "inherit",
            }}
          >
            ← Back
          </button>
          <button
            type="button"
            onClick={handleConfirm}
            disabled={!selected || confirming}
            style={{
              padding: "12px 28px", borderRadius: 12, border: "none",
              background: profile ? "linear-gradient(135deg," + profile.color + "," + profile.color + "dd)" : "#cbd5e1",
              color: "#fff", fontSize: 14, fontWeight: 800, cursor: !selected || confirming ? "not-allowed" : "pointer",
              opacity: !selected ? 0.55 : confirming ? 0.75 : 1,
              boxShadow: profile ? "0 6px 20px rgba(0,0,0,0.12)" : "none",
              fontFamily: "inherit",
            }}
          >
            {confirming ? "Setting up…" : "Continue →"}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{
      position: embed ? "relative" : "fixed",
      inset: embed ? "auto" : 0,
      background: embed ? "transparent" : "linear-gradient(135deg,#06101f 0%,#0d1e38 50%,#080f1e 100%)",
      display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "flex-start",
      fontFamily: "'Plus Jakarta Sans',system-ui,sans-serif", overflowY: embed ? "visible" : "auto", zIndex: embed ? "auto" : 9999
    }}>
      <div style={{ width: "100%", maxWidth: 920, padding: embed ? "0 0 24px" : "32px 20px 140px", boxSizing: "border-box" }}>
        {/* Light content panel */}
        <div style={{
          background: LP.paper,
          borderRadius: 24,
          boxShadow: LP.shadow,
          border: "1px solid rgba(255,255,255,0.85)",
          padding: "32px 28px 36px",
          boxSizing: "border-box"
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 4 }}>
            <div style={{ width: 44, height: 44, borderRadius: 12, background: "#f1f5f9", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "inset 0 1px 0 rgba(255,255,255,0.9)" }}>
              <img src={TECHON_LOGO} alt="Techon ERP" style={{ width: 32, height: 32, objectFit: "contain" }} />
            </div>
            <div>
              <div style={{ fontSize: 12, color: "#3b82f6", fontWeight: 800, letterSpacing: "0.12em", textTransform: "uppercase" }}>Techon ERP</div>
              <div style={{ fontSize: 11, color: LP.muted, fontWeight: 600 }}>One-time Business Setup</div>
            </div>
          </div>
          <div style={{ marginTop: 22, marginBottom: 4 }}>
            <div style={{ fontSize: 26, fontWeight: 900, color: LP.text, letterSpacing: "-0.02em", lineHeight: 1.25 }}>
              What type of business are you setting up?
            </div>
            <div style={{ fontSize: 14, color: LP.muted, marginTop: 10, fontWeight: 500, lineHeight: 1.55 }}>
              This configures your ERP for the right modules, units and categories. Choose carefully — this cannot be changed later.
            </div>
          </div>

          {/* Search bar */}
          <div style={{ position: "relative", marginTop: 22, marginBottom: 22 }}>
            <span style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", fontSize: 15, opacity: 0.45 }}>🔍</span>
            <input
              autoFocus
              placeholder="Search your business type — e.g. mobile, salon, pharmacy, hardware…"
              value={search}
              onChange={function (e) { setSearch(e.target.value); setSelected(null); }}
              style={{
                width: "100%", boxSizing: "border-box", padding: "13px 40px 13px 42px",
                background: LP.inputBg, border: "1.5px solid " + LP.border,
                borderRadius: 14, fontSize: 14, color: LP.text, outline: "none",
                fontFamily: "'Plus Jakarta Sans',sans-serif", fontWeight: 500,
                transition: "border-color .2s, box-shadow .2s"
              }}
              onFocus={function (e) { e.target.style.borderColor = LP.selRing; e.target.style.boxShadow = "0 0 0 3px rgba(59,130,246,0.15)"; }}
              onBlur={function (e) { e.target.style.borderColor = LP.border; e.target.style.boxShadow = "none"; }}
            />
            {search && (
              <button type="button" onClick={function () { setSearch(""); setSelected(null); }} style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", color: "#94a3b8", fontSize: 20, cursor: "pointer", lineHeight: 1, padding: 4 }}>×</button>
            )}
          </div>

          {/* No results */}
          {filtered.length === 0 && (
            <div style={{ textAlign: "center", padding: "40px 12px", color: LP.muted, fontSize: 14 }}>
              No business type matched &quot;{search}&quot;. Try a different keyword or choose <strong style={{ color: LP.text }}>General Retail</strong>.
            </div>
          )}

          {/* Cards grid — horizontal rows, light cards */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: 12 }}>
            {filtered.map(function (key) {
              var p = BUSINESS_PROFILES[key];
              var isSelected = selected === key;
              var isHov = hovered === key;
              return (
                <div
                  key={key}
                  onClick={function () { handleCardClick(key); }}
                  onMouseEnter={function () { setHovered(key); }}
                  onMouseLeave={function () { setHovered(null); }}
                  style={{
                    background: isSelected ? LP.selBg : "#ffffff",
                    border: isSelected ? "2px solid " + LP.selRing : "1px solid " + (isHov ? "#cbd5e1" : LP.border),
                    borderRadius: 16,
                    padding: "16px 14px 14px 16px",
                    cursor: "pointer",
                    transition: "all .18s",
                    position: "relative",
                    overflow: "hidden",
                    boxShadow: isSelected ? "0 4px 16px rgba(59,130,246,0.12)" : LP.cardShadow
                  }}
                >
                  {isSelected && (
                    <div style={{
                      position: "absolute", bottom: 10, right: 10, width: 22, height: 22, borderRadius: "50%",
                      background: LP.selRing, display: "flex", alignItems: "center", justifyContent: "center",
                      fontSize: 11, color: "#fff", fontWeight: 900, boxShadow: "0 2px 8px rgba(59,130,246,0.4)"
                    }}>✓</div>
                  )}
                  <div style={{ display: "flex", gap: 14, alignItems: "flex-start" }}>
                    <div style={{ fontSize: 34, lineHeight: 1, flexShrink: 0 }}>{p.emoji}</div>
                    <div style={{ flex: 1, minWidth: 0, paddingRight: isSelected ? 20 : 0 }}>
                      <div style={{ fontSize: 15, fontWeight: 800, color: isSelected ? LP.selRing : LP.text, marginBottom: 6, letterSpacing: "-0.01em" }}>{p.name}</div>
                      <div style={{ fontSize: 11, color: "#64748b", lineHeight: 1.55, fontWeight: 500 }}>{p.covers}</div>
                      <div style={{ display: "flex", flexWrap: "wrap", gap: 5, marginTop: 10 }}>
                        {p.modules.repairs && <span style={{ fontSize: 9.5, background: "#fee2e2", color: "#b91c1c", borderRadius: 6, padding: "3px 8px", fontWeight: 700, letterSpacing: "0.03em" }}>REPAIRS</span>}
                        {p.modules.expiry && <span style={{ fontSize: 9.5, background: "#fef9c3", color: "#854d0e", borderRadius: 6, padding: "3px 8px", fontWeight: 700, letterSpacing: "0.03em" }}>EXPIRY</span>}
                        {p.modules.serial && <span style={{ fontSize: 9.5, background: "#e0f2fe", color: "#0369a1", borderRadius: 6, padding: "3px 8px", fontWeight: 700, letterSpacing: "0.03em" }}>SERIAL/IMEI</span>}
                        <span style={{ fontSize: 9.5, background: "#f1f5f9", color: "#475569", borderRadius: 6, padding: "3px 8px", fontWeight: 700, letterSpacing: "0.03em" }}>{p.units.length} UNITS</span>
                        <span style={{ fontSize: 9.5, background: "#f1f5f9", color: "#475569", borderRadius: 6, padding: "3px 8px", fontWeight: 700, letterSpacing: "0.03em" }}>{p.categories.length} CATEGORIES</span>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Sticky confirm bar — light strip on dark bg (in wizard: in-flow sticky) */}
      <div style={{
        position: embed ? "sticky" : "fixed",
        bottom: 0, left: embed ? "auto" : 0, right: embed ? "auto" : 0,
        background: embed ? "transparent" : "linear-gradient(180deg, rgba(6,16,31,0) 0%, rgba(6,16,31,0.85) 18%, #06101f 100%)",
        padding: embed ? "12px 0 0" : "16px 20px 24px", display: "flex", justifyContent: "center", zIndex: embed ? 5 : 10000,
        transform: selected ? "translateY(0)" : "translateY(100%)",
        transition: "transform .25s cubic-bezier(.4,0,.2,1)",
        width: embed ? "100%" : "auto",
        maxWidth: embed ? 920 : "none",
        margin: embed ? "0 auto" : "0"
      }}>
        <div style={{
          width: "100%", maxWidth: 920, display: "flex", alignItems: "center", gap: 14,
          background: "#ffffff", borderRadius: 16, padding: "14px 18px",
          boxShadow: "0 -4px 24px rgba(0,0,0,0.12)", border: "1px solid " + LP.border
        }}>
          {profile && (
            <div style={{ flex: 1, display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}>
              <span style={{ fontSize: 24 }}>{profile.emoji}</span>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontSize: 14, fontWeight: 800, color: LP.text }}>{profile.name}</div>
                <div style={{ fontSize: 11, color: LP.muted, fontWeight: 500 }}>
                  {profile.units.length} units · {profile.categories.length} categories
                  {profile.modules.repairs ? " · Repairs module" : ""}
                  {profile.modules.expiry ? " · Expiry tracking" : ""}
                </div>
              </div>
            </div>
          )}
          <button
            onClick={handleConfirm}
            disabled={confirming}
            style={{
              background: profile ? "linear-gradient(135deg," + profile.color + "," + profile.color + "cc)" : "#2979ff",
              color: "#fff", border: "none", borderRadius: 12, padding: "13px 28px",
              fontSize: 14, fontWeight: 800, cursor: confirming ? "default" : "pointer",
              opacity: confirming ? 0.7 : 1, letterSpacing: "-0.01em", flexShrink: 0,
              boxShadow: profile ? "0 4px 16px " + profile.color + "55" : "0 4px 14px rgba(41,121,255,0.35)",
              transition: "all .15s"
            }}
          >
            {confirming ? "Setting up…" : "Confirm & Continue →"}
          </button>
        </div>
      </div>
    </div>
  );
};

